import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { LEVELS, create, replay, solve } from '../src';
import type { GameAction } from '../src';

const lines: string[] = [
  '# Level solvability report',
  '',
  'Generated by `npm run verify:levels` (exhaustive breadth-first search over the real engine, run phase analysed in isolation).',
  '',
  '- **Dead** = reachable world state from which no win exists (only RESET escapes). **Irreversible** = state that can never return to the start without RESET (a pushed block or a spent rune is irreversible but not dead).',
  '- **Shift essential** = the level has a rule change *and* no action sequence that avoids it can win (proved by pruning every epoch-1 state and re-searching). "by budget" = a change-free route exists but needs more actions than the run allows.',
  '',
  '| Level | Scout / Run budget | Optimal run | Slack | Distinct optimal | Reachable | Dead | Irreversible | Shift essential | Replay-verified | Verdict |',
  '|---|---|---|---|---|---|---|---|---|---|---|',
];
let failed = false;
const detail: string[] = [];

for (const level of LEVELS) {
  create(level, 'verify'); // throws on structurally invalid challenges
  const r = solve(level);
  const hasShift = !!level.rules.shift;
  const ignoring = hasShift ? solve(level, { stayInEpoch0: true }) : null;
  const plan: GameAction[] = [...(level.budget.explore > 0 ? [{ type: 'COMMIT' } as const] : []), ...(r.optimalSolution ?? [])];
  const outcome = r.optimalSolution ? replay(level, plan) : null;
  const verified = !!outcome && outcome.won && outcome.runActions === r.optimalLength && !outcome.extraActions;
  // Essential outright (cannot be won without the change) or essential for the budget (the change-free route exists but does not fit the run).
  const shiftOk = !hasShift || (ignoring !== null && (!ignoring.solvable || (ignoring.optimalLength as number) > level.budget.execute));
  const shiftHow = !hasShift ? 'n/a' : !shiftOk ? 'NO' : ignoring !== null && ignoring.solvable ? 'by budget' : 'yes';
  const ok = r.solvable && r.withinBudget && verified && r.deadStates === 0 && shiftOk;
  if (!ok) failed = true;
  lines.push(
    `| ${level.id} | ${level.budget.explore} / ${level.budget.execute} | ${r.optimalLength ?? '—'} | ${r.optimalLength === null ? '—' : level.budget.execute - r.optimalLength} | ${r.optimalSolutionCount} | ${r.reachableStates} | ${r.deadStates} | ${r.irreversibleStates} | ${shiftHow} | ${verified ? 'yes' : 'NO'} | ${ok ? 'PASS' : 'FAIL'} |`,
  );
  detail.push(`- **${level.id}**: \`${(r.optimalSolution ?? []).map((a) => (a.type === 'MOVE' ? a.direction[0] : a.type === 'INTERACT' ? `[${a.targetId}]` : a.type)).join(' ')}\``);
}
lines.push('', '## One optimal run per level (U/D/L/R = move, [id] = interact)', '', ...detail, '');
const out = fileURLToPath(new URL('../../../docs/verification/solvability-report.md', import.meta.url));
writeFileSync(out, lines.join('\n'));
console.log(lines.join('\n'));
if (failed) {
  console.error('\nSOLVABILITY VERIFICATION FAILED');
  process.exit(1);
}
